import sys
f=sys.argv[1];s=open(f,encoding='utf-8').read()
def rep(old,new,cnt=1):
    global s
    assert s.count(old)==cnt,(old[:70],s.count(old));s=s.replace(old,new)
# Theme Park set pieces, round two: the park gate arch, a big top, a pirate ship, the mascot statue, arcade cabinets,
# a claw machine, swan boats, flume logs, the fairy castle, fireworks overhead, a teacup ride.
KIT=r"""
function parkGateSprite(w){const c=mk(w,46),g=c.getContext('2d');for(const x of [0,w-16]){R(g,x,6,16,40,K);R(g,x+1,7,14,38,'#9b5fd6');for(let y=10;y<44;y+=6)R(g,x+1,y,14,2,'#7a3fb8');R(g,x,0,16,8,K);R(g,x+1,1,14,6,'#ffc727');R(g,x+5,-2,6,4,'#e03a4e');}
  R(g,12,6,w-24,18,K);R(g,13,7,w-26,16,'#e03a4e');for(let x=14;x<w-14;x+=8)R(g,x,7,4,16,'#ffc727');R(g,(w>>1)-34,2,68,20,K);R(g,(w>>1)-33,3,66,18,'#13306b');sprText(g,'SNOW PARK',(w>>1)-sprTextW('SNOW PARK')/2|0,6,'#ffd23f');sprText(g,'* * *',(w>>1)-sprTextW('* * *')/2|0,13,'#ff4fa3');R(g,12,4,w-24,3,PAL.W);return c;}
function bigTopSprite(a){const c=mk(76,60),g=c.getContext('2d'),col=['#e03a4e','#3f86d6','#9b5fd6'][a%3];for(let y=0;y<44;y++){const hw=Math.round(6+y*0.75);R(g,38-hw,y+8,hw*2,1,K);if(y>0)for(let x=38-hw+1;x<38+hw-1;x++)R(g,x,y+8,1,1,((x-38)*44/(y+1)|0)%2===0?col:'#f4f8ff');}
  R(g,36,0,4,10,K);R(g,37,1,2,8,'#ffc727');R(g,40,0,8,4,col);R(g,4,50,68,10,K);R(g,5,51,66,8,col);for(let x=6;x<70;x+=6)R(g,x,51,3,8,'#f4f8ff');R(g,30,50,16,10,K);R(g,31,51,14,9,'#2a1f40');R(g,10,8,56,3,PAL.W);return c;}
function pirateSprite(){const c=mk(70,52),g=c.getContext('2d');R(g,32,0,6,46,K);R(g,33,1,4,44,'#8a5a34');R(g,8,4,54,4,K);R(g,9,5,52,2,'#55607a');for(const x of [10,58])R(g,x,4,3,42,'#55607a');
  for(let y=0;y<16;y++){const hw=Math.round(30-Math.abs(y-8)*0.6-(y>10?(y-10)*1.5:0));R(g,35-hw,26+y,hw*2,1,K);if(y>0&&y<15)R(g,36-hw,26+y,hw*2-2,1,y<5?'#c98d4a':'#8a5a34');}R(g,6,26,58,2,PAL.W);for(let x=12;x<60;x+=8)R(g,x,32,4,3,'#ffc727');R(g,30,10,10,14,K);R(g,31,11,8,12,'#f4f8ff');R(g,33,13,4,4,K);R(g,0,46,70,6,K);R(g,1,47,68,4,'#8793a8');return c;}
function mascotSprite(){const c=mk(26,40),g=c.getContext('2d');R(g,2,32,22,8,K);R(g,3,33,20,6,'#c6c0b0');R(g,3,33,20,1,PAL.W);g.fillStyle=K;pixCircle(g,13,22,9);pixCircle(g,13,10,7);pixCircle(g,7,4,3);pixCircle(g,19,4,3);g.fillStyle='#a8673a';pixCircle(g,13,22,8);pixCircle(g,13,10,6);pixCircle(g,7,4,2);pixCircle(g,19,4,2);g.fillStyle='#e8c87a';pixCircle(g,13,24,4);pixCircle(g,13,12,3);R(g,10,8,2,2,K);R(g,15,8,2,2,K);R(g,12,11,3,2,K);R(g,9,15,9,2,'#e03a4e');R(g,7,3,12,2,PAL.W);return c;}
function arcadeSprite(a){const c=mk(14,22),g=c.getContext('2d'),col=['#e03a4e','#3f86d6','#33b24a','#9b5fd6','#ffc727'][a%5];R(g,0,0,14,22,K);R(g,1,1,12,20,col);R(g,2,3,10,8,K);R(g,3,4,8,6,['#7ad3ff','#ff4fa3','#9cff7a'][a%3]);R(g,4,6,2,2,'#ffffff');R(g,2,13,10,3,'#2a2a36');R(g,4,13,2,2,'#e03a4e');R(g,8,14,2,1,'#ffc727');R(g,1,0,12,1,PAL.W);return c;}
function clawSprite(){const c=mk(20,28),g=c.getContext('2d');R(g,0,0,20,28,K);R(g,1,1,18,26,'#ff4fa3');R(g,2,3,16,14,K);R(g,3,4,14,12,'#bfe6ff');for(let k=0;k<6;k++)R(g,4+(k*5)%12,10+(k%2)*3,3,3,['#ffc727','#e03a4e','#33b24a','#3f86d6'][k%4]);R(g,9,4,2,5,'#55607a');R(g,7,9,6,2,'#55607a');R(g,2,19,16,6,'#2a2a36');R(g,1,0,18,1,PAL.W);return c;}
function swanSprite(){const c=mk(18,24),g=c.getContext('2d');R(g,1,8,16,16,K);R(g,2,9,14,14,'#f4f8ff');R(g,3,10,12,4,'#c6d9f3');R(g,6,0,6,10,K);R(g,7,1,4,9,'#f4f8ff');R(g,8,2,2,2,K);R(g,11,3,3,2,'#f07a1a');R(g,4,14,10,7,'#3f86d6');return c;}
function logSprite(){const c=mk(14,28),g=c.getContext('2d');R(g,0,0,14,28,K);R(g,1,1,12,26,'#8a5a34');R(g,1,1,12,3,'#c98d4a');for(let y=6;y<26;y+=5)R(g,2,y,10,1,'#6b4a2c');R(g,3,10,8,10,'#2a1f1a');R(g,4,12,2,3,'#f6c7a1');R(g,8,14,2,3,'#f6c7a1');return c;}
function castleSprite(){const c=mk(100,96),g=c.getContext('2d');R(g,10,40,80,56,K);R(g,11,41,78,54,'#e8e0f4');for(let y=44;y<94;y+=6)for(let x=12+((y/6|0)%2)*4;x<88;x+=8)R(g,x,y,6,1,'#c6bce0');
  for(const [x,h] of [[0,70],[78,70],[38,90]]){R(g,x,96-h,22,h,K);R(g,x+1,97-h,20,h-2,'#f4eefc');for(let k=0;k<4;k++)R(g,x+1+k*6,96-h-4,4,5,K);g.fillStyle=K;for(let y=0;y<22;y++){const hw=Math.round(y*0.55)+1;g.fillRect(x+11-hw,96-h-26+y,hw*2,1);}g.fillStyle='#9b5fd6';for(let y=1;y<22;y++){const hw=Math.round(y*0.55);g.fillRect(x+11-hw,96-h-26+y,hw*2,1);}R(g,x+10,96-h-30,2,6,K);R(g,x+12,96-h-30,6,4,'#ff4fa3');R(g,x+7,96-h+10,8,10,K);R(g,x+8,96-h+11,6,9,'#ffd77a');}
  R(g,40,72,20,24,K);R(g,41,73,18,23,'#6b3f22');g.fillStyle=K;pixCircle(g,50,72,10);g.fillStyle='#6b3f22';pixCircle(g,50,73,9);R(g,49,62,2,34,'#4a2a16');for(const x of [6,84])R(g,x,0,1,1,K);R(g,10,40,80,3,PAL.W);return c;}
function fireworksOverSprite(a){const c=mk(60,44),g=c.getContext('2d'),cols=[['#ff4fa3','#ffd23f'],['#7ad3ff','#ffffff'],['#9cff7a','#ffd23f'],['#ff7a3a','#ff4fa3']];for(let b=0;b<3;b++){const cx=12+b*18+(a*7)%9,cy=12+((b*13+a*5)%18),r=8+((a+b)%3)*2,col=cols[(a+b)%4];for(let k=0;k<12;k++){const an=k*Math.PI/6+b;for(let q=2;q<r;q+=2){R(g,Math.round(cx+Math.cos(an)*q),Math.round(cy+Math.sin(an)*q),1,1,q>r-3?col[1]:col[0]);}}R(g,cx,cy,1,1,'#ffffff');}return c;}
function teacupRideSprite(){const c=mk(70,52),g=c.getContext('2d');g.fillStyle=K;for(let y=0;y<44;y++){const hw=Math.round(35*Math.sqrt(Math.max(0,1-((y-22)/22)**2)));g.fillRect(35-hw,y+6,hw*2,1);}g.fillStyle='#9fd4f4';for(let y=1;y<43;y++){const hw=Math.round(34*Math.sqrt(Math.max(0,1-((y-22)/21)**2)));g.fillRect(35-hw,y+6,hw*2,1);}
  const cols=['#ff4fa3','#ffc727','#33b24a','#3f86d6','#e03a4e'];for(let k=0;k<5;k++){const an=k*Math.PI*2/5,x=Math.round(35+Math.cos(an)*20),y=Math.round(28+Math.sin(an)*12);R(g,x-6,y-5,12,10,K);R(g,x-5,y-4,10,8,cols[k]);R(g,x-4,y-4,8,3,'#f4f8ff');R(g,x+5,y-2,3,3,K);}R(g,30,22,10,10,K);R(g,31,23,8,8,'#ffc727');R(g,33,0,4,24,K);R(g,34,1,2,22,'#e03a4e');R(g,30,0,10,4,'#ffc727');return c;}
"""
rep("function buildFromData(g,D,setT,ob,setCircle,paintText){", KIT+"\nfunction buildFromData(g,D,setT,ob,setCircle,paintText){")
rep("  iceblock:{arg:14,","  bigtop:{arg:0,min:0,max:2,make:a=>bigTopSprite(a),foot:()=>[4,24,68,36]},\n  pirate:{make:()=>scnSpr('pr',pirateSprite),foot:()=>[0,40,70,12]},\n  mascot:{make:()=>scnSpr('ms',mascotSprite),foot:()=>[2,30,22,10]},\n  arcade:{arg:0,min:0,max:4,make:a=>arcadeSprite(a),foot:()=>[0,12,14,10]},\n  claw:{make:()=>scnSpr('cl',clawSprite),foot:()=>[0,16,20,12]},\n  swan:{make:()=>scnSpr('sw',swanSprite),foot:()=>[1,8,16,16]},\n  log:{make:()=>scnSpr('lg',logSprite),foot:()=>[0,0,14,28]},\n  castle:{make:()=>scnSpr('cs',castleSprite),foot:()=>[0,40,100,56]},\n  teacups:{make:()=>scnSpr('tc',teacupRideSprite),foot:()=>[2,14,66,38]},\n  iceblock:{arg:14,")
